<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { assetCategoryLabels, assetBusinessLevelLabels, assetStatutoryCategoryLabels, ApiError, describeError, formatDate, request, workspacePath, type Workspace } from './api'
import { catalogKinds, catalogMetadataFields, type CatalogEntry } from './discovery'
import Icon from './Icon.vue'
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>()
const base=workspacePath(props.workspace.slug)+'/catalog', home=`#/${encodeURIComponent(props.workspace.slug)}`
const entries=ref<CatalogEntry[]>([]), kind=ref(''), search=ref(''), error=ref(''), notice=ref(''), busy=ref(false), truncated=ref(false)
const selected=ref<CatalogEntry|null>(null), metadata=ref<Record<string,string>>({}), history=ref<{revision:number;origin:string;metadata:unknown;createdAt:string}[]>([])
const cmdb=ref(''), showImport=ref(false), detailTab=ref('observed'), editingMetadata=ref(false), conflict=ref(false), loaded=ref(false)
const editor=ref<HTMLElement|null>(null), editable=computed(()=>['owner','operator'].includes(props.workspace.role)), summary=ref<Record<string,number>>({})
const active=new AbortController();let choice=0
const path=computed(()=>selected.value?[selected.value.database,selected.value.schema,selected.value.table,selected.value.field].filter(Boolean):[])
const conflictKeys=computed(()=>Object.keys(selected.value?.conflicts??{}))
function failed(e:unknown){if(active.signal.aborted)return;if(e instanceof ApiError&&e.status===401){emit('sessionExpired');return}error.value=describeError(e)}
function conflictObservation(key:string){const raw=selected.value?.conflicts[key];return raw&&typeof raw==='object'&&!Array.isArray(raw)&&'incoming' in raw?value(raw.incoming):value(raw)}
function conflictSource(key:string){const raw=selected.value?.conflicts[key];return raw&&typeof raw==='object'&&!Array.isArray(raw)&&'source' in raw?value(raw.source):''}
function value(v:unknown){if(v===null||v===undefined||v==='')return '未记录';return typeof v==='object'?JSON.stringify(v):String(v)}
async function load(){busy.value=true;error.value='';try{const [r,s]=await Promise.all([request<{items:CatalogEntry[];truncated:boolean}>(base+'?'+new URLSearchParams({kind:kind.value,q:search.value}),{signal:active.signal}),request<Record<string,number>>(base+'/summary',{signal:active.signal})]);entries.value=r.items;truncated.value=r.truncated;summary.value=s;loaded.value=true;if(!editingMetadata.value){const entry=entries.value.find(e=>e.id===selected.value?.id)??entries.value[0];if(entry)await choose(entry);else selected.value=null}}catch(e){failed(e)}finally{busy.value=false}}
async function choose(entry:CatalogEntry){if(editingMetadata.value&&selected.value?.id!==entry.id)return;selected.value=entry;metadata.value={};conflict.value=false;for(const k of Object.keys(catalogMetadataFields))metadata.value[k]=String(entry.confirmedMetadata[k]??entry.metadata[k]??'');history.value=[];const current=++choice;try{const r=await request<{items:typeof history.value}>(base+'/'+entry.id+'/history',{signal:active.signal});if(current===choice)history.value=r.items}catch(e){failed(e)}}
async function cancelMetadata(){editingMetadata.value=false;conflict.value=false;error.value='';if(selected.value)await choose(selected.value)}
async function edit(){if(!selected.value)return;editingMetadata.value=true;detailTab.value='confirmed';await nextTick();editor.value?.focus({preventScroll:true});editor.value?.scrollIntoView({block:'start',behavior:'smooth'})}
async function save(){if(!selected.value||!editable.value||conflict.value||busy.value)return;busy.value=true;error.value='';try{await request(base+'/'+selected.value.id+'/metadata',{method:'PUT',body:JSON.stringify({revision:selected.value.revision,metadata:metadata.value}),signal:active.signal});notice.value='业务属性已确认，后续来源冲突将单独显示。';const id=selected.value.id;editingMetadata.value=false;await load();const entry=entries.value.find(e=>e.id===id);if(entry)await choose(entry)}catch(e){conflict.value=e instanceof ApiError&&e.status===409;if(conflict.value)error.value='目录版本已变化。未保存的输入已保留，请显式重新读取后核对。';else failed(e)}finally{busy.value=false}}
async function reloadMetadata(){const id=selected.value?.id;if(!id)return;await load();const current=entries.value.find(e=>e.id===id);if(current){editingMetadata.value=false;await choose(current);await edit()}}
async function importCMDB(){if(!editable.value||busy.value)return;busy.value=true;try{const payload=JSON.parse(cmdb.value);const r=await request<{imported:number;replayed:boolean;conflicts:number}>(base+'/cmdb',{method:'POST',body:JSON.stringify(payload),signal:active.signal});notice.value=`导入 ${r.imported} 项，${r.conflicts} 项属性冲突${r.replayed?'（幂等重放）':''}。`;showImport.value=false;await load()}catch(e){failed(e)}finally{busy.value=false}}
function example(){cmdb.value=JSON.stringify({version:1,source:'enterprise-cmdb',batchId:'synthetic-cmdb-001',records:[{sourceRef:'business-order',parentRef:'',kind:'business',name:'合成订单业务',system:'commerce',metadata:{ownerTeam:'业务运营',businessOrganization:'零售事业部',region:'中国',sharingRecipients:'内部财务',retention:'按经确认的业务保留规则执行'}},{sourceRef:'order-app',parentRef:'business-order',kind:'application',name:'合成订单应用',system:'commerce',metadata:{business:'合成订单业务',ownerTeam:'研发团队'}}]},null,2)}
function count(k:string){return entries.value.filter(e=>e.kind===k).length}
onMounted(()=>void load());onBeforeUnmount(()=>active.abort())
</script>
<template>
<section class="catalog-page" :aria-busy="busy">
  <header class="page-header"><div><p class="eyebrow">数据治理 / 资产目录</p><h1>业务与数据资产目录</h1><p>业务、应用、库表和字段共用明确身份，来源观察与人工确认分别留存。</p></div><div class="page-actions"><button v-if="editable" class="button button-secondary" type="button" @click="showImport=!showImport">导入 CMDB</button><button v-if="editable&&selected&&!editingMetadata" class="button button-primary" type="button" @click="edit">确认属性</button></div></header>
  <p v-if="error" role="alert" class="message message-error">{{error}}</p><p v-if="notice" role="status" class="message message-success">{{notice}}</p>
  <div class="catalog-stats scope-strip"><span>目录资产 <strong>{{loaded?summary.entries:'—'}}</strong></span><span>表 / 集合 <strong>{{loaded?summary.tables:'—'}}</strong></span><span>字段 / 路径 <strong>{{loaded?summary.fields:'—'}}</strong></span><span>当前来源 <strong>{{loaded?summary.currentSources:'—'}} / {{loaded?summary.sources:'—'}}</strong></span><span>规则证据 <strong>{{loaded?summary.ruleHits:'—'}}</strong></span></div>
  <nav v-if="selected" class="catalog-path" aria-label="当前目录层次"><span class="badge">{{catalogKinds[selected.kind]||selected.kind}}</span><template v-for="(segment,index) in path" :key="index"><Icon name="chevron"/><span>{{segment}}</span></template><span v-if="!path.length">{{selected.name}}</span></nav>
  <form v-if="showImport" class="panel catalog-import" @submit.prevent="importCMDB"><div class="panel-heading"><div><h2>CMDB 标准导入</h2><p>按 sourceRef 或明确的 assetId 定位对象，保留人工属性与来源冲突。</p></div><button class="button button-secondary" type="button" @click="showImport=false">关闭</button></div><div class="catalog-import-body"><p class="field-hint">新对象使用 sourceRef 幂等合并；跨工作区资产会拒绝。以下示例仅为合成数据。</p><button type="button" class="button button-secondary" @click="example">填入合成示例</button><div class="field"><label for="catalog-cmdb">CMDB JSON</label><textarea id="catalog-cmdb" v-model="cmdb" rows="10" required></textarea></div><button class="button button-primary" :disabled="busy">{{busy?'导入中…':'执行导入'}}</button></div></form>
  <div v-if="!editingMetadata" class="catalog-explorer">
    <aside class="panel catalog-tree"><div class="panel-heading"><h2>业务目录</h2></div><nav aria-label="目录对象类型"><button type="button" :class="{active:!kind}" :aria-pressed="!kind" @click="kind='';load()"><Icon name="assets"/>全部对象</button><button v-for="(label,k) in catalogKinds" :key="k" type="button" :class="{active:kind===k}" :aria-pressed="kind===k" @click="kind=String(k);load()"><Icon :name="k==='business'||k==='application'?'workspace':'assets'"/>{{label}}<span v-if="!kind">{{count(String(k))}}</span></button></nav><p class="field-hint">按已登记层次浏览。名称相同不表示同一对象，也不自动建立血缘。</p></aside>
    <section class="panel catalog-register"><div class="panel-heading"><div><h2>数据目录</h2><p>已加载 {{entries.length}} 项{{truncated?' · 达到展示上限':''}}</p></div><button class="button button-secondary" type="button" :disabled="busy" @click="load">刷新</button></div><form class="filter-bar catalog-filters" @submit.prevent="load"><label for="catalog-kind">对象类型</label><select id="catalog-kind" v-model="kind"><option value="">全部</option><option v-for="(label,k) in catalogKinds" :key="k" :value="k">{{label}}</option></select><label class="visually-hidden" for="catalog-search">搜索目录</label><input id="catalog-search" v-model="search" maxlength="160" placeholder="搜索名称、来源或库表字段"><button class="button button-secondary" :disabled="busy">查询</button></form>
      <p v-if="busy&&!loaded" role="status" class="empty-state">正在读取目录…</p><div class="table-scroll" role="region" tabindex="0" aria-label="目录资产"><table class="data-table"><thead><tr><th scope="col">名称 / 身份</th><th scope="col">类型</th><th scope="col">责任团队</th><th scope="col">来源 / 状态</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.id" :class="{selected:selected?.id===entry.id}"><th scope="row"><button class="catalog-select" type="button" :aria-pressed="selected?.id===entry.id" @click="choose(entry)">{{entry.name}}</button><span class="table-secondary mono">Asset #{{entry.assetId}} · {{[entry.database,entry.schema,entry.table,entry.field].filter(Boolean).join(' / ')||entry.parentRef}}</span></th><td>{{catalogKinds[entry.kind]}}</td><td>{{entry.confirmedMetadata.ownerTeam||entry.metadata.ownerTeam||'待确认'}}<span class="table-secondary">{{entry.confirmedMetadata.business||entry.metadata.business||'业务待补充'}}</span></td><td>{{entry.source}}<span class="table-secondary"><span class="badge" :class="entry.current?'status-verified':'status-draft'">{{entry.current?'当前批次':'过期 / 未观察'}}</span><span v-if="Object.keys(entry.conflicts).length" class="badge status-needs_work">属性冲突</span></span></td><td><button class="button button-secondary" type="button" @click="choose(entry)">详情 / 历史</button></td></tr></tbody></table><p v-if="loaded&&!entries.length" class="empty-state">当前条件下暂无目录资产。可调整筛选，或完成采集与 CMDB 导入。</p></div>
    </section>
    <aside class="context-rail section-stack"><section class="panel catalog-summary"><div class="panel-heading"><h2>属性与来源</h2></div><template v-if="selected"><div class="catalog-summary-body"><h3>{{selected.name}}</h3><p class="field-hint">目录修订 v{{selected.revision}} · Asset #{{selected.assetId}}</p><dl class="catalog-definitions"><div><dt>来源</dt><dd>{{selected.source}}</dd></div><div><dt>观察时间</dt><dd>{{formatDate(selected.observedAt)}}</dd></div><div><dt>数据属性</dt><dd>{{assetCategoryLabels[selected.category]||'待分类'}}</dd></div><div><dt>业务级别</dt><dd>{{assetBusinessLevelLabels[selected.businessLevel]||'待分级'}}</dd></div><div><dt>法定类别</dt><dd>{{assetStatutoryCategoryLabels[selected.statutoryCategory]||'待认定'}}</dd></div></dl><button v-if="editable" class="button button-primary" type="button" @click="edit">确认属性与冲突</button><a class="table-link" :href="home+'/classification/'+selected.assetId">查看分类依据</a></div><div class="catalog-tabs" role="group" aria-label="目录详情"><button v-for="tab in [{id:'observed',name:'来源观察'},{id:'confirmed',name:'人工确认'},{id:'history',name:'变更历史'}]" :key="tab.id" type="button" :class="{active:detailTab===tab.id}" :aria-pressed="detailTab===tab.id" @click="detailTab=tab.id">{{tab.name}}</button></div><div class="catalog-tab-content"><template v-if="detailTab==='observed'"><p class="field-hint">来源内容与人工采用值分别保存。</p><details><summary>自动元数据与规则命中</summary><pre>{{JSON.stringify(selected.metadata,null,2)}}</pre></details></template><dl v-else-if="detailTab==='confirmed'" class="catalog-definitions"><div v-for="(label,key) in catalogMetadataFields" :key="key"><dt>{{label}}</dt><dd>{{value(selected.confirmedMetadata[key])}}</dd></div></dl><template v-else><details v-for="h in history" :key="h.revision"><summary>v{{h.revision}} · {{h.origin}}<time>{{formatDate(h.createdAt)}}</time></summary><pre>{{JSON.stringify(h.metadata,null,2)}}</pre></details><p v-if="!history.length" class="field-hint">暂无修订记录。</p></template></div></template><p v-else class="empty-state">选择一个目录对象，查看来源、人工属性和修订历史。</p></section><section class="panel"><div class="panel-heading"><h2>范围说明</h2></div><p class="catalog-summary-body field-hint">元数据、内容识别、数据库授权与流转关系分别取证。OpenMetadata 标签或所有者不能作为数据库 ACL 证明。</p></section></aside>
  </div>
  <div v-else-if="selected" class="form-workbench catalog-editor"><aside class="panel"><div class="panel-heading"><h2>确认步骤</h2></div><ol class="workflow-spine catalog-editor-steps"><li>来源观察</li><li>人工确认</li><li>冲突与历史</li></ol></aside><div class="section-stack form-main"><section class="panel"><div class="panel-heading"><div><h2 ref="editor" tabindex="-1">业务属性确认与来源冲突</h2><p>{{selected.name}} · Asset #{{selected.assetId}} · v{{selected.revision}}</p></div></div><form class="metadata-form" @submit.prevent="save"><div v-for="(label,key) in catalogMetadataFields" :key="key" class="field" :class="{'metadata-wide':key==='description'}"><label :for="'metadata-'+key">{{label}}</label><textarea v-if="key==='description'" :id="'metadata-'+key" v-model="metadata[key]" :readonly="!editable||busy||conflict" maxlength="1000" rows="3"></textarea><input v-else :id="'metadata-'+key" v-model="metadata[key]" :readonly="!editable||busy||conflict" maxlength="1000"></div><div class="form-actions metadata-wide"><button class="button button-secondary" type="button" :disabled="busy" @click="cancelMetadata">取消</button><button v-if="conflict" class="button button-secondary" type="button" :disabled="busy" @click="reloadMetadata">重新读取并替换草稿</button><button v-if="editable" class="button button-primary" :disabled="busy||conflict">{{busy?'保存中…':'确认业务属性'}}</button></div></form></section><section class="panel"><div class="panel-heading"><h2>来源冲突与人工采用</h2><span class="badge" :class="conflictKeys.length?'status-needs_work':'status-draft'">{{conflictKeys.length}} 项冲突</span></div><div v-if="conflictKeys.length" class="table-scroll"><table class="data-table"><thead><tr><th>属性</th><th>来源观察</th><th>人工采用</th></tr></thead><tbody><tr v-for="key in conflictKeys" :key="key"><th>{{catalogMetadataFields[key]||key}}</th><td>{{conflictObservation(key)}}<span v-if="conflictSource(key)" class="table-secondary">来源：{{conflictSource(key)}}</span></td><td>{{value(selected.confirmedMetadata[key])}}</td></tr></tbody></table></div><p v-else class="empty-state">当前没有来源属性冲突。</p></section></div><aside class="form-aside context-rail section-stack"><section class="panel"><div class="panel-heading"><h2>采用范围</h2></div><dl class="catalog-definitions catalog-summary-body"><div><dt>当前修订</dt><dd>v{{selected.revision}}</dd></div><div><dt>来源</dt><dd>{{selected.source}}</dd></div><div><dt>对象</dt><dd>{{catalogKinds[selected.kind]}}</dd></div></dl></section><section class="panel"><div class="panel-heading"><h2>确认提示</h2></div><p class="catalog-summary-body field-hint">确认值优先保留。后续采集出现不同属性时单独记入冲突，保存版本变化须重新核对；草稿不会自动覆盖。</p></section></aside></div>
</section>
</template>
<style scoped>
