tr.selected th{box-shadow:inset 1px 0 var(--accent)}.catalog-select{font:inherit;border:0;background:none;color:var(--ink);font-weight:700;text-align:left;cursor:pointer;padding:0;overflow-wrap:anywhere}.catalog-select:hover{color:var(--accent)}.catalog-summary-body{padding:18px;display:grid;gap:12px;overflow-wrap:anywhere}.catalog-summary-body h3{font-size:14px}.catalog-definitions{margin:0;display:grid;font-size:12px}.catalog-definitions>div{display:grid;grid-template-columns:78px minmax(0,1fr);gap:10px;padding:10px 0;border-bottom:1px solid var(--line)}.catalog-definitions dt{color:var(--secondary)}.catalog-definitions dd{margin:0;overflow-wrap:anywhere}.catalog-tabs{display:flex;flex-wrap:wrap;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:0 10px}.catalog-tabs button{border:0;border-bottom:2px solid transparent;background:none;color:var(--secondary);padding:12px 7px;cursor:pointer;font-size:12px}.catalog-tabs button.active{color:var(--accent);border-bottom-color:var(--accent)}.catalog-tab-content{padding:14px;font-size:12px}.catalog-tab-content time{display:block;color:var(--secondary);font-size:12px}.catalog-page pre{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:380px;overflow:auto}.catalog-page details{margin:10px 0}.catalog-page summary{cursor:pointer;overflow-wrap:anywhere}.catalog-import-body{padding:18px;display:grid;gap:14px}.catalog-import-body textarea{font-family:ui-monospace,monospace}.catalog-editor{grid-template-columns:190px minmax(0,1fr) 290px}.catalog-editor-steps{padding:22px 22px 22px 35px;font-size:12px;line-height:2.8}.metadata-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;padding:20px}.metadata-form .field{margin:0;min-width:0}.metadata-wide{grid-column:1/-1}.catalog-import textarea,.metadata-form :is(input,textarea){width:100%;min-width:0}.catalog-editor .form-actions{justify-content:flex-end;margin:0;padding-top:18px;border-top:1px solid var(--line)}
@media(max-width:1400px){.catalog-explorer{grid-template-columns:160px minmax(0,1fr) 260px}.catalog-editor{grid-template-columns:160px minmax(0,1fr) 260px}.catalog-register .button{padding:6px 8px;font-size:12px;white-space:nowrap}.catalog-filters input{max-width:150px}}
.catalog-page .button.button-primary{border-color:var(--accent);color:#fff;background:var(--accent)}.catalog-page .button.button-primary:hover{background:var(--accent-hover)}.catalog-page .catalog-register .data-table{min-width:650px}.catalog-page .data-table tbody th{background:transparent;color:var(--ink);font-size:12px}.catalog-register>.table-scroll{max-height:calc(100vh - 500px);min-height:320px;overflow:auto}.catalog-editor .catalog-editor-steps{display:grid;gap:22px;line-height:1.8}.catalog-editor .catalog-editor-steps>li+li::before{left:-15px;top:-17px;width:1px;height:20px}.catalog-editor .form-actions{position:sticky;bottom:0;background:var(--surface)}
.catalog-page .catalog-editor .data-table{min-width:0;table-layout:fixed}.catalog-editor .data-table :is(th,td){overflow-wrap:anywhere}.catalog-editor .data-table th:first-child{width:24%}.catalog-editor .data-table td{width:38%}
</style>
